function ChapterDialog:SetContentName(owner)
    assert(type(owner) == "number")
    --self.TxtLeftName.text = owner
    --KTool.SetActive(self.LeftTitle.gameObject, not string.isEmpty(owner))
    local role = self.RoleSetting:Get(owner);
    if role ~= nil then
        --printInfo(owner)
        local scheme = isSet(ChapterConstants.ChapterOwner, owner) and ChapterConstants.ChapterOwner[owner] or ChapterConstants.ChapterOwner[1]
        self.TxtLeftName.text = string.format(scheme, role.name)
    else
        self.TxtLeftName.text = "invaild parameters " .. owner
    end
end

function ChapterDialog:FinishType()
    if self._init == nil then
        return
    end
    if self.IsTyping then
        if self._dialogCo ~= nil then
            cs_coroutine.stop(self._dialogCo)
            self._dialogCo = nil
        end
        local txtContent = self:GetTextComp(self._cachedVo.owner)
        txtContent:StopType()
        txtContent:ShowAll()
        if self._finishCall ~= nil then
            self._finishCall()
            self._finishCall = nil
        end
        --self.TxtContent:InvokeEndCall()
    end
end

function ChapterDialog:SetAutoPlay(state)
    if state then
        if not self.IsTyping and not self.HasOption then
            printInfo("Invoke")
            self.ScreenBtn.onClick:Invoke()
        end
    end
    self.AutoPlay = state
    printInfo("SetAutoPlay ")
    printInfo(state)
end

function ChapterDialog:SetVisible(state)
    if state then
        self.AutoPlay = false
    else
        self.AutoPlay = self.controller.Argument.parameters.Processor.IsAutoPlay

    end
    self:FinishType()
    KTool.SetActive(self.MainDialog, not state)
    KTool.SetActive(self.Option, not state)
    printInfo("SetVisible ")
    printInfo(state)
end

function ChapterDialog:ProcessEvent(event)
    --assert(type(event) == "string")

    print(table.dump(event))
    for i = 1, #event do
        if event[i] == "Resume" then
            --self.Processor.DirectorControl:ResumeCurrent()
            self._processor:ResumeDirector()
        elseif event[i] == "SplitlineEffect" then
            self._splitlineEffect = true
        
        end
    end
end

function ChapterDialog:SetIconHead(icon)

    if self._cachedPath == icon then
        return
    end

    self._cachedPath = icon

    if string.isEmpty(icon) then
        KTool.SetActive(self.IconHead.transform.parent.gameObject, false)
        KTool.SetActive(self.IconHead.gameObject, false)
        return
    end

    printInfo("SetIconHead %s", icon)
    
    if not KTool.IsActiveInHierarchy(self.IconHead.transform.parent) then
        printInfo("active parent")
        KTool.SetActive(self.IconHead.transform.parent, true)
    end
    
    if not KTool.IsActiveInHierarchy(self.IconHead.gameObject) then
        printInfo("active icon")
        KTool.SetActive(self.IconHead.gameObject, true)
    end
    
    
    self.IconHead:LoadSprite(icon)
end

function ChapterDialog:ResetArgs()
    self._splitlineEffect = false
end

function ChapterDialog:SetFrameLayout(ownerId)
    local layout = isSet(ChapterConstants.ChapterLayout, ownerId) and ChapterConstants.ChapterLayout[ownerId] or ChapterConstants.ChapterLayout[1]
    KTool.SetActive(self.Frames.gameObject, true)
    KTool.SetActive(self.DialogFrame.gameObject, false)
    KTool.SetActive(self.ThoughtFrame.gameObject, false)
    KTool.SetActive(self.Titles.gameObject, true)
    KTool.SetActive(self.SelfTitle.gameObject, false)
    KTool.SetActive(self.OtherTitle.gameObject, false)
    KTool.SetActive(self.TxtContent.gameObject, false)
    KTool.SetActive(self.TxtContent2.gameObject, false)
    KTool.SetActive(self[layout.frame].gameObject, layout.frameActive)
    KTool.SetActive(self[layout.title].gameObject, layout.titleActive)
    KTool.SetActive(self[layout.comp].gameObject, true)
end

function ChapterDialog:GetTextComp(ownerId)
    --printInfo("GetTextComp %d", ownerId)
    local layout = isSet(ChapterConstants.ChapterLayout, ownerId) and ChapterConstants.ChapterLayout[ownerId] or ChapterConstants.ChapterLayout[1]
    return self[layout.comp]
end

function ChapterDialog:FillPlaceHold(origin, ownerId)
    local playerComp = ChapterUtils.GetPlayerComp()
    local result = origin
    result = ChapterUtils.ReplaceStr(result, "#playerName", playerComp.playerDojo.playerName)
    result = ChapterUtils.ReplaceStr(result, "#playerId", playerComp.playerDojo.playerId)
    result = ChapterUtils.ReplaceStr(result, "$n", "\n")

    if isSet(ChapterConstants.ChapterScheme, ownerId) then
        result = string.format(ChapterConstants.ChapterScheme[ownerId].scheme, result)
    end

    return result
end

function ChapterDialog:SetButtonClick(button, callback)
    if button and button.onClick then
        button.onClick:RemoveAllListeners()
        button.onClick:AddListener(callback)
    else
        print("set click event failed ,type not button")
    end
end

return ChapterDialog